/// <summary>
/// Tells SVG and HTML apart from ordinary XML and reports script they carry.
/// </summary>
public final class FOSecureContentInspectorMarkup extends FOSecureContentInspector
{
    private const int MaxScanChars = 524288;
    private const int MaxPrologSteps = 64;
    private const int MaxAttributeValue = 4096;
    private const int MaxTags = 20000;
    private const int MaxHandlerLetters = 20;
    private const int MaxEntityLength = 10;
    private const int MinHandlerLetters = 2;

}

Method.Source:
/// <summary>
/// Whether a character code may appear in an element name.
/// </summary>
/// <param name = "_code">The character code.</param>
/// <returns>true for a letter, digit, hyphen, dot, colon or underscore.</returns>
private static boolean isNameChar(int _code)
{
    return FOSecureContentWindow::isAsciiLetter(_code)
        || FOSecureContentWindow::isDigit(_code)
        || _code == FOSecureContentConstants::Hyphen
        || _code == FOSecureContentConstants::Dot
        || _code == FOSecureContentConstants::Colon
        || _code == FOSecureContentConstants::Underscore;
}

/// <summary>
/// Strips a namespace prefix from a qualified name.
/// </summary>
/// <param name = "_qualifiedName">A name that may carry a prefix.</param>
/// <returns>The local part.</returns>
private static str localName(str _qualifiedName)
{
    int colon = FOSecureContentWindow::indexOfOrdinalOneBased(_qualifiedName, ':');

    return colon > 0 ? subStr(_qualifiedName, colon + 1, strLen(_qualifiedName) - colon) : _qualifiedName;
}

/// <summary>
/// Decodes the window into text the rules can scan.
/// </summary>
/// <param name = "_window">The content.</param>
/// <returns>The text, or an empty string when it could not be decoded.</returns>
public static str scannableText(FOSecureContentWindow _window)
{
    int           first     = _window.byteAt(0);
    int           second    = _window.byteAt(1);
    int           third     = _window.byteAt(2);
    int           headBytes = _window.headLength();
    boolean       isUtf16Le = first == FOSecureContentConstants::Utf16LeMarkFirst
        && second == FOSecureContentConstants::Utf16LeMarkSecond;
    boolean       isUtf16Be = first == FOSecureContentConstants::Utf16BeMarkFirst
        && second == FOSecureContentConstants::Utf16BeMarkSecond;
    System.Byte[] raw;

    if (isUtf16Le || isUtf16Be)
    {
        raw = _window.bytes(0, headBytes);

        if (raw == null || headBytes <= 2)
        {
            return '';
        }

        return System.Text.Encoding::GetEncoding(isUtf16Le
            ? FOSecureContentConstants::Utf16LeCodePage
            : FOSecureContentConstants::Utf16BeCodePage)
            .GetString(raw, 2, headBytes - 2);
    }

    if (first == FOSecureContentConstants::Utf8MarkFirst
        && second == FOSecureContentConstants::Utf8MarkSecond
        && third == FOSecureContentConstants::Utf8MarkThird)
    {
        return _window.textAt(3, headBytes - 3);
    }

    return _window.textAt(0, headBytes);
}

/// <summary>
/// Finds the end of a document type declaration.
/// </summary>
/// <param name = "_text">The text.</param>
/// <param name = "_onePosition">Where the declaration starts.</param>
/// <returns>The one based position just past it, or 0.</returns>
private static int endOfDoctype(str _text, int _onePosition)
{
    int     length   = strLen(_text);
    int     position = _onePosition;
    boolean inSubset;
    int     code;

    while (position <= length)
    {
        code = char2Num(_text, position);

        if (code == FOSecureContentConstants::LeftBracket)
        {
            inSubset = true;
        }
        else if (code == FOSecureContentConstants::RightBracket)
        {
            inSubset = false;
        }
        else if (code == FOSecureContentConstants::GreaterThan && !inSubset)
        {
            return position + 1;
        }

        position++;
    }

    return 0;
}

/// <summary>
/// Finds the root element name, skipping whatever prolog precedes it.
/// </summary>
/// <param name = "_text">The markup.</param>
/// <returns>The lowercased local name, or an empty string.</returns>
public static str rootElementName(str _text)
{
    int length   = strLen(_text);
    int position = 1;
    int steps;
    int closing;
    str name;

    while (position <= length && steps < FOSecureContentInspectorMarkup::MaxPrologSteps)
    {
        steps++;

        while (position <= length && FOSecureContentWindow::isSpace(char2Num(_text, position)))
        {
            position++;
        }

        if (position > length
            || char2Num(_text, position) != FOSecureContentConstants::LessThan)
        {
            return '';
        }

        if (subStr(_text, position, 4) == '<!--')
        {
            closing = FOSecureContentWindow::indexOfOrdinalOneBased(_text, '-->', position + 4);

            if (!closing)
            {
                return '';
            }

            position = closing + 3;
            continue;
        }

        if (subStr(_text, position, 9) == '<!DOCTYPE')
        {
            position = FOSecureContentInspectorMarkup::endOfDoctype(_text, position);

            if (!position)
            {
                return '';
            }

            continue;
        }

        if (subStr(_text, position, 2) == '<?')
        {
            closing = FOSecureContentWindow::indexOfOrdinalOneBased(_text, '?>', position + 2);

            if (!closing)
            {
                return '';
            }

            position = closing + 2;
            continue;
        }

        if (subStr(_text, position, 2) == '<!')
        {
            closing = FOSecureContentWindow::indexOfOrdinalOneBased(_text, '>', position + 2);

            if (!closing)
            {
                return '';
            }

            position = closing + 1;
            continue;
        }

        position++;

        while (position <= length
            && FOSecureContentInspectorMarkup::isNameChar(char2Num(_text, position)))
        {
            name += subStr(_text, position, 1);
            position++;
        }

        return FOSecureContentInspectorMarkup::localName(strLwr(name));
    }

    return '';
}

/// <summary>
/// Reduces an attribute value to what a browser would act on.
/// </summary>
/// <param name = "_value">The raw attribute value.</param>
/// <returns>Numeric entities decoded, control characters removed, lowercased.</returns>
private static str normalizeAttributeValue(str _value)
{
    str source = strLen(_value) > FOSecureContentInspectorMarkup::MaxAttributeValue
        ? subStr(_value, 1, FOSecureContentInspectorMarkup::MaxAttributeValue)
        : _value;
    str result;
    str entity;
    int length   = strLen(source);
    int position = 1;
    int semicolon;
    int code;

    while (position <= length)
    {
        if (char2Num(source, position) == FOSecureContentConstants::Ampersand
            && char2Num(source, position + 1) == FOSecureContentConstants::NumberSign)
        {
            semicolon = FOSecureContentWindow::indexOfOrdinalOneBased(source, ';', position + 2);

            if (semicolon > 0
                && semicolon - position <= FOSecureContentInspectorMarkup::MaxEntityLength)
            {
                entity = subStr(source, position + 2, semicolon - position - 2);

                code = strLwr(subStr(entity, 1, 1)) == 'x'
                    ? hex2Int(subStr(entity, 2, strLen(entity) - 1))
                    : str2Int(entity);

                if (code > FOSecureContentConstants::PrintableMin
                    && code < FOSecureContentConstants::PrintableMax)
                {
                    result += num2Char(code);
                }

                position = semicolon + 1;
                continue;
            }
        }

        if (char2Num(source, position) > FOSecureContentConstants::PrintableMin)
        {
            result += subStr(source, position, 1);
        }

        position++;
    }

    return strLwr(result);
}

/// <summary>
/// Whether an attribute value is a script URL.
/// </summary>
/// <param name = "_value">The raw attribute value.</param>
/// <returns>true for a javascript, vbscript or inline html data scheme.</returns>
private static boolean isScriptUrl(str _value)
{
    str normalized = FOSecureContentInspectorMarkup::normalizeAttributeValue(_value);

    return FOSecureContentWindow::indexOfOrdinal(normalized, 'javascript:') == 0
        || FOSecureContentWindow::indexOfOrdinal(normalized, 'vbscript:') == 0
        || FOSecureContentWindow::indexOfOrdinal(normalized, 'data:text/html') == 0;
}

/// <summary>
/// Whether an attribute value points outside the file.
/// </summary>
/// <param name = "_value">The raw attribute value.</param>
/// <returns>true for an absolute, protocol relative or data reference.</returns>
private static boolean isExternalReference(str _value)
{
    str normalized = FOSecureContentInspectorMarkup::normalizeAttributeValue(_value);

    return FOSecureContentWindow::indexOfOrdinal(normalized, 'http:') == 0
        || FOSecureContentWindow::indexOfOrdinal(normalized, 'https:') == 0
        || FOSecureContentWindow::indexOfOrdinal(normalized, '//') == 0
        || FOSecureContentWindow::indexOfOrdinal(normalized, 'data:') == 0;
}

/// <summary>
/// Whether a tag carries an inline event handler attribute.
/// </summary>
/// <param name = "_tagText">One tag, angle bracket to angle bracket.</param>
/// <returns>true when an on-something attribute is assigned.</returns>
private static boolean hasEventHandlerAttribute(str _tagText)
{
    int length   = strLen(_tagText);
    int position = 2;
    int scan;
    int letters;

    while (position < length)
    {
        if (!FOSecureContentWindow::isSpace(char2Num(_tagText, position)))
        {
            position++;
            continue;
        }

        scan = position + 1;

        if (strLwr(subStr(_tagText, scan, 2)) != 'on')
        {
            position++;
            continue;
        }

        scan += 2;
        letters = 0;

        while (scan <= length
            && letters <= FOSecureContentInspectorMarkup::MaxHandlerLetters
            && FOSecureContentWindow::isAsciiLetter(char2Num(_tagText, scan)))
        {
            scan++;
            letters++;
        }

        while (scan <= length && FOSecureContentWindow::isSpace(char2Num(_tagText, scan)))
        {
            scan++;
        }

        if (letters >= FOSecureContentInspectorMarkup::MinHandlerLetters
            && scan <= length
            && subStr(_tagText, scan, 1) == '=')
        {
            return true;
        }

        position++;
    }

    return false;
}

/// <summary>
/// Collects the quoted attribute values of one tag.
/// </summary>
/// <param name = "_tagText">One tag.</param>
/// <returns>A container of raw values.</returns>
private static container attributeValues(str _tagText)
{
    container values;
    str       quote;
    int       length   = strLen(_tagText);
    int       position = 1;
    int       equals;
    int       valueStart;
    int       valueEnd;

    while (position < length)
    {
        equals = FOSecureContentWindow::indexOfOrdinalOneBased(_tagText, '=', position);

        if (!equals || equals >= length)
        {
            break;
        }

        position = equals + 1;

        while (position <= length && FOSecureContentWindow::isSpace(char2Num(_tagText, position)))
        {
            position++;
        }

        quote = subStr(_tagText, position, 1);

        if (quote != '"' && quote != '\'')
        {
            continue;
        }

        valueStart = position + 1;
        valueEnd   = FOSecureContentWindow::indexOfOrdinalOneBased(_tagText, quote, valueStart);

        if (!valueEnd)
        {
            break;
        }

        values  += [subStr(_tagText, valueStart, valueEnd - valueStart)];
        position = valueEnd + 1;
    }

    return values;
}

/// <summary>
/// The element name of one tag.
/// </summary>
/// <param name = "_tagText">One tag.</param>
/// <returns>The lowercased local name.</returns>
private static str tagElementName(str _tagText)
{
    int position = 2;
    int length   = strLen(_tagText);
    str name;

    if (char2Num(_tagText, position) == FOSecureContentConstants::Solidus)
    {
        position++;
    }

    while (position <= length
        && FOSecureContentInspectorMarkup::isNameChar(char2Num(_tagText, position)))
    {
        name += subStr(_tagText, position, 1);
        position++;
    }

    return FOSecureContentInspectorMarkup::localName(strLwr(name));
}

/// <summary>
/// Reports the active content a markup document carries.
/// </summary>
/// <param name = "_text">The decoded markup.</param>
/// <returns>The findings. Never null.</returns>
public static FOSecureContentFindings scanForActiveContent(str _text)
{
    FOSecureContentFindings findings = FOSecureContentFindings::empty();
    container values;
    str       tagText;
    str       elementName;
    int       length = strLen(_text) < FOSecureContentInspectorMarkup::MaxScanChars
        ? strLen(_text)
        : FOSecureContentInspectorMarkup::MaxScanChars;
    int       position = 1;
    int       tagStart;
    int       tagEnd;
    int       tags;
    int       i;
    boolean   sawScript;
    boolean   sawHandler;
    boolean   sawScriptUrl;
    boolean   sawFrame;
    boolean   sawForeignObject;
    boolean   sawExternalUse;

    while (position <= length && tags < FOSecureContentInspectorMarkup::MaxTags)
    {
        tagStart = FOSecureContentWindow::indexOfOrdinalOneBased(_text, '<', position);

        if (!tagStart || tagStart > length)
        {
            break;
        }

        tagEnd = FOSecureContentWindow::indexOfOrdinalOneBased(_text, '>', tagStart + 1);

        if (!tagEnd || tagEnd > length)
        {
            break;
        }

        tags++;
        tagText     = subStr(_text, tagStart, tagEnd - tagStart + 1);
        position    = tagEnd + 1;
        elementName = FOSecureContentInspectorMarkup::tagElementName(tagText);

        switch (elementName)
        {
            // handler and listener are SVG Tiny and SMIL.
            case 'script':
            case 'handler':
            case 'listener':
                sawScript = true;
                break;

            case 'iframe':
            case 'object':
            case 'embed':
            case 'frame':
            case 'frameset':
                sawFrame = true;
                break;

            case 'foreignobject':
                sawForeignObject = true;
                break;
        }

        if (!sawHandler && FOSecureContentInspectorMarkup::hasEventHandlerAttribute(tagText))
        {
            sawHandler = true;
        }

        values = FOSecureContentInspectorMarkup::attributeValues(tagText);

        for (i = 1; i <= conLen(values); i++)
        {
            if (!sawScriptUrl && FOSecureContentInspectorMarkup::isScriptUrl(conPeek(values, i)))
            {
                sawScriptUrl = true;
            }

            if (!sawExternalUse
                && elementName == 'use'
                && FOSecureContentInspectorMarkup::isExternalReference(conPeek(values, i)))
            {
                sawExternalUse = true;
            }
        }
    }

    if (sawScript)
    {
        findings = findings.with(FOSecureContentFinding::construct(
            FOSecureActiveContentKind::Script,
            FOSecureContentConstants::MarkupScriptEvidence));
    }

    if (sawHandler)
    {
        findings = findings.with(FOSecureContentFinding::construct(
            FOSecureActiveContentKind::Script,
            FOSecureContentConstants::MarkupEventHandlerEvidence));
    }

    if (sawScriptUrl)
    {
        findings = findings.with(FOSecureContentFinding::construct(
            FOSecureActiveContentKind::Script,
            FOSecureContentConstants::MarkupJavaScriptUrlEvidence));
    }

    if (sawFrame)
    {
        findings = findings.with(FOSecureContentFinding::construct(
            FOSecureActiveContentKind::ExternalReference,
            FOSecureContentConstants::MarkupFrameEvidence));
    }

    if (sawForeignObject)
    {
        findings = findings.with(FOSecureContentFinding::construct(
            FOSecureActiveContentKind::ExternalReference,
            FOSecureContentConstants::MarkupForeignObjectEvidence));
    }

    if (sawExternalUse)
    {
        findings = findings.with(FOSecureContentFinding::construct(
            FOSecureActiveContentKind::ExternalReference,
            FOSecureContentConstants::MarkupExternalUseEvidence));
    }

    if (FOSecureContentWindow::indexOfOrdinal(_text, '<!ENTITY') >= 0)
    {
        findings = findings.with(FOSecureContentFinding::construct(
            FOSecureActiveContentKind::ExternalEntity,
            FOSecureContentConstants::MarkupExternalEntityEvidence));
    }

    return findings;
}

/// <summary>
/// Identifies a markup document and reports what it carries.
/// </summary>
/// <param name = "_window">The content to inspect.</param>
/// <param name = "_claimedExtension">The extension the file claims, normalized.</param>
/// <returns>What was concluded. Never null, and never throws.</returns>
public FOSecureContentInspection inspect(FOSecureContentWindow _window, str _claimedExtension)
{
    FOSecureContentInspection result = FOSecureContentInspection::inconclusive();
    str                       text;
    str                       root;

    if (!this.canInspect(_window))
    {
        return result;
    }

    try
    {
        text = FOSecureContentInspectorMarkup::scannableText(_window);

        if (!text)
        {
            return result.withUnassessable();
        }

        root = FOSecureContentInspectorMarkup::rootElementName(text);

        if (root == 'svg')
        {
            result = result.withRefinedType('svg', 'SVG image');
        }
        else if (root == 'html')
        {
            result = result.withRefinedType('', 'HTML document');
        }

        result = result.withFindings(FOSecureContentInspectorMarkup::scanForActiveContent(text));

        if (_window.isTruncated())
        {
            result = result.withUnassessable();
        }
    }
    catch (Exception::CLRError)
    {
        exceptionTextFallThrough();
    }
    catch (Exception::Error)
    {
        exceptionTextFallThrough();
    }

    return result;
}
